fn carry_fork_files(src_base: &std::path::Path, new_base: &std::path::Path, leader: &str) -> Result<(), String> {
    let src_member = src_base.join("members").join(leader);
    let new_member = new_base.join("members").join(leader);
    std::fs::create_dir_all(&new_member).map_err(|e| e.to_string())?;
    for name in FORK_CHAT_FILES {
        let src = src_member.join(name);
        if src.is_file() {
            std::fs::copy(&src, new_member.join(name)).map_err(|e| e.to_string())?;
        }
    }
    for name in FORK_SESSION_FILES {
        let src = src_base.join(name);
        if src.is_file() {
            std::fs::copy(&src, new_base.join(name)).map_err(|e| e.to_string())?;
        }
    }
    Ok(())
}

